"""Import selected numerical facts from the public INDB workbook; never invent portions.
Usage: python3 scripts/import-indb.py /path/to/Anuvaad_INDB_2024.11.xlsx
Requires openpyxl for development only. Legacy references retained for backward compatibility.
"""
import json,re,sys,hashlib,subprocess,collections
from pathlib import Path
import openpyxl
base=Path(__file__).resolve().parents[1]
legacy=json.loads(subprocess.check_output(['node','-e',"console.log(JSON.stringify(require('./app/src/main/assets/food-reference.js').filter(f=>!f.id.startsWith('indb-')&&!f.id.startsWith('recipe-'))))"],cwd=base,text=True))
rows=list(openpyxl.load_workbook(sys.argv[1],read_only=True,data_only=True).active.values)[1:]
new=[]
for r in rows:
 code,name,_,_,energy=r[:5];name=str(name).strip()
 if not isinstance(energy,(int,float)) or not 0<=energy<=900:continue
 unit=str(r[42] or '').strip();se=r[44];protein=r[6];sp=r[46]
 review=energy>500 or (isinstance(se,(int,float)) and se>1200)
 units={'g':round(energy/100,6)};pu={} if protein is None else {'g':round(protein/100,6)}
 serving=isinstance(se,(int,float)) and se>0 and unit and not review and (energy==0 or 1<=se/energy*100<=600)
 if serving:
  units['serving']=round(se,4)
  if sp is not None:pu['serving']=round(sp,4)
  direct={'bowl':'bowl','cup':'cup','glass':'glass','plate':'plate','piece':'piece','slice':'slice','tablespoon':'tbsp','teaspoon':'tsp'}
  count=['chapati','roti','parantha','dosa','idli','vada','poori','naan','egg','samosa','cheela','uttapam','appam','thepla','pesarattu','ladoo','burfi','biscuit','cookie','cutlet','pakora','kebab','kachori','kofta','dhokla']
  u=direct.get(unit,'piece' if unit in count else None)
  if u:units[u]=round(se,4);pu.update({u:round(sp,4)} if sp is not None else {})
 aliases=[name.lower()];outer=re.sub(r'\([^)]*\)','',name).strip();aliases.append(outer.lower())
 for part in re.findall(r'\(([^)]+)\)',name)+[outer]:
  for a in part.split('/'):
   a=a.lower().strip();
   if len(a)>=3:aliases.append(a)
 new.append(dict(id='indb-'+str(code),name=name,aliases=list(dict.fromkeys(aliases)),defaultUnit='serving' if serving else 'g',defaultQty=1 if serving else 100,units=units,proteinUnits=pu,note=('Review required: this source recipe has an unusually high energy density or serving total. Use a product label or reviewed manual estimate.' if review else 'INDB standard recipe; oil, ingredients and portion size vary.')+(' Source serving: 1 '+unit+'.' if serving else ' Use weighed grams; no reliable count/cup portion is enabled.'),source='Anuvaad INDB 2024.11 · '+str(code),sourceUrl='https://www.anuvaad.org.in/indian-nutrient-databank/',reviewRequired=review,sourceServing=unit))
# Avoid silently resolving ambiguous names, or changing established reference aliases.
occupied={a.lower() for f in legacy for a in f['aliases']};freq=collections.Counter(a for f in new for a in f['aliases'])
for f in new:f['aliases']=[a for a in f['aliases'] if a not in occupied and freq[a]==1]
# Explicit app-authored ingredient models fill common naming gaps, not lab values.
recipes=[
 ('chicken-biryani','Chicken biryani',['chicken biryani','chicken biriyani','chicken dum biryani'],[('168878',200),('171477',100),('171025',10),('171284',50),('170457',50)]),
 ('egg-biryani','Egg biryani',['egg biryani','egg biriyani','anda biryani'],[('168878',200),('173424',100),('171025',10),('171284',50),('170457',50)]),
 ('curd-rice','Curd rice',['curd rice','daddojanam','thayir sadam'],[('168878',150),('171284',100),('171025',3)]),
 ('chole','Chole curry',['chole','chole curry','chana masala'],[('173757',150),('170457',50),('171025',5)]),
 ('egg-bhurji','Egg bhurji',['egg bhurji','anda bhurji'],[('173424',100),('170457',50),('171025',5)]),
 ('rajma-curry','Rajma curry',['rajma curry','rajma masala'],[('175194',150),('170457',50),('171025',5)])
]
byid={f['id']:f for f in legacy};derived=[]
for code,name,aliases,ingredients in recipes:
 mass=sum(g for _,g in ingredients);cal=sum(byid[i]['units']['g']*g for i,g in ingredients);protein=sum(byid[i]['proteinUnits']['g']*g for i,g in ingredients)
 derived.append(dict(id='recipe-'+code,name=name,aliases=aliases,defaultUnit='serving',defaultQty=1,units={'serving':round(cal,4),'g':round(cal/mass,6)},proteinUnits={'serving':round(protein,4),'g':round(protein/mass,6)},source='App ingredient model · USDA SR Legacy references',note='Illustrative recipe, not a measured regional standard. 1 serving = '+str(mass)+' g: '+', '.join(str(g)+' g '+byid[i]['name'] for i,g in ingredients)+'. Seasonings not modelled. Adjust for your recipe.',reviewRequired=False))
reserved={a for f in derived for a in f['aliases']}
for f in new:f['aliases']=[a for a in f['aliases'] if a not in reserved]
allfoods=legacy+new+derived
(base/'data/food-catalog.json').write_text(json.dumps(allfoods,ensure_ascii=False,indent=2)+'\n')
(base/'app/src/main/assets/food-reference.js').write_text('/* Numerical reference facts; see FOOD_SOURCES.md. Generated by scripts/import-indb.py. */\n(function(root){const foods='+json.dumps(allfoods,ensure_ascii=False,separators=(',',':'))+";if(typeof module==='object'&&module.exports)module.exports=foods;else root.FOOD_REFERENCE=foods;})(typeof globalThis!=='undefined'?globalThis:this);\n")
(base/'data/catalog-provenance.json').write_text(json.dumps({'source':'Anuvaad INDB 2024.11','url':'https://www.anuvaad.org.in/wp-content/uploads/2020/07/Anuvaad_INDB_2024.11.xlsx','sha256':hashlib.sha256(Path(sys.argv[1]).read_bytes()).hexdigest(),'sourceRows':len(rows),'importedRows':len(new),'reviewRequiredRows':sum(f['reviewRequired'] for f in new),'legacyRows':len(legacy),'note':'Selected numerical energy/protein facts only. Review flags are app heuristics, not corrections or validation of source accuracy.'},indent=2)+'\n')
print(len(allfoods),'foods;',sum(f['reviewRequired'] for f in new),'require review')
